mapper.select:
SELECT p.id, p.user_id, p.title, p.content, p.preference, p.scope, p.type, p.target_count, p.current_count,
       p.location, p.latitude, p.longitude, p.plan_time, p.plan_end_time, p.cover_image, p.status, p.view_count,
       p.create_time, p.update_time, p.create_by, p.update_by, p.deleted
FROM t_partner p
LEFT JOIN t_user u ON p.user_id = u.id
WHERE p.deleted = 0
  AND p.status = 0

    AND p.type = #{type}



    AND p.location LIKE #{locationPattern} ESCAPE '\'


    AND p.plan_time >= #{planTimeStart}


    AND p.plan_time <= #{planTimeEnd}


    AND u.gender = #{gender}

ORDER BY p.create_time DESC
